using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class CompactFarmStatics {
 const string A="Assets/NewMap/FiveHangars/CombinedStatic";static int serial,sourceCount,resultCount;static Mesh cube;static List<string> report;
 static Mesh Combine(MeshRenderer[] rs,Transform parent,string name,out Material[] materials){var mats=rs.SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var parts=new List<Mesh>();foreach(var mat in mats){var ci=new List<CombineInstance>();foreach(var r in rs){var mf=r.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)continue;var m=mf.sharedMesh;for(int s=0;s<m.subMeshCount;s++)if(r.sharedMaterials[Mathf.Min(s,r.sharedMaterials.Length-1)]==mat)ci.Add(new CombineInstance{mesh=m,subMeshIndex=s,transform=parent.worldToLocalMatrix*r.transform.localToWorldMatrix});}var sub=new Mesh{indexFormat=IndexFormat.UInt32};sub.CombineMeshes(ci.ToArray(),true,true);parts.Add(sub);}
 var result=new Mesh{name=name,indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);result.RecalculateBounds();AssetDatabase.CreateAsset(result,A+"/Static "+(++serial)+".asset");foreach(var m in parts)Object.DestroyImmediate(m);materials=mats;return result;}
 static MeshRenderer Bake(MeshRenderer[] rs,Transform parent,string name){var g=new GameObject(name);g.transform.SetParent(parent,false);Material[] mats;g.AddComponent<MeshFilter>().sharedMesh=Combine(rs,g.transform,name,out mats);var r=g.AddComponent<MeshRenderer>();r.sharedMaterials=mats;r.shadowCastingMode=rs[0].shadowCastingMode;r.receiveShadows=rs[0].receiveShadows;r.lightProbeUsage=rs[0].lightProbeUsage;r.reflectionProbeUsage=rs[0].reflectionProbeUsage;sourceCount+=rs.Length;resultCount++;return r;}
 static void Collision(Transform t){var colliders=t.GetComponentsInChildren<Collider>().Where(c=>c.enabled&&!c.isTrigger&&(c is BoxCollider||c is MeshCollider)).ToArray();var ci=new List<CombineInstance>();foreach(var c in colliders){if(c is BoxCollider b)ci.Add(new CombineInstance{mesh=cube,transform=t.worldToLocalMatrix*b.transform.localToWorldMatrix*Matrix4x4.TRS(b.center,Quaternion.identity,b.size)});else if(c is MeshCollider m&&m.sharedMesh)ci.Add(new CombineInstance{mesh=m.sharedMesh,transform=t.worldToLocalMatrix*m.transform.localToWorldMatrix});}if(ci.Count==0)return;var mesh=new Mesh{name=t.name+" collision",indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(ci.ToArray(),true,true);AssetDatabase.CreateAsset(mesh,A+"/Collision "+(++serial)+".asset");var go=new GameObject("Combined static collision");go.transform.SetParent(t,false);go.AddComponent<MeshCollider>().sharedMesh=mesh;foreach(var c in colliders)Object.DestroyImmediate(c);}
 static void Remove(MeshRenderer[] rs){foreach(var r in rs){var mf=r.GetComponent<MeshFilter>();Object.DestroyImmediate(r);if(mf)Object.DestroyImmediate(mf);}}
 static void Prune(Transform t){foreach(var c in t.Cast<Transform>().ToArray()){Prune(c);if(c&&c.childCount==0&&c.GetComponents<Component>().Length==1)Object.DestroyImmediate(c.gameObject);}}
 static void Unpack(Transform t){var top=PrefabUtility.GetOutermostPrefabInstanceRoot(t.gameObject);if(top)PrefabUtility.UnpackPrefabInstance(top,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);}
 static void CompactLODs(Transform area){foreach(var lod in area.GetComponentsInChildren<LODGroup>().OrderByDescending(l=>Depth(l.transform)).ToArray()){
  if(lod.GetComponentsInChildren<MonoBehaviour>().Any()||lod.GetComponentsInChildren<BillboardRenderer>().Any())continue;
  Unpack(lod.transform);var levels=lod.GetLODs();var originals=levels.SelectMany(l=>l.renderers).OfType<MeshRenderer>().Distinct().ToArray();
  for(int i=0;i<levels.Length;i++){var rs=levels[i].renderers.OfType<MeshRenderer>().Where(r=>r&&r.GetComponent<MeshFilter>()).ToArray();if(rs.Length==0)continue;levels[i].renderers=new Renderer[]{Bake(rs,lod.transform,"Combined LOD "+i)};}
  Collision(lod.transform);lod.SetLODs(levels);Remove(originals);Prune(lod.transform);lod.RecalculateBounds();
 }}
 static int Depth(Transform t){int n=0;while(t.parent){n++;t=t.parent;}return n;}
 static void Flat(Transform t){Unpack(t);var rs=t.GetComponentsInChildren<MeshRenderer>().Where(r=>!r.GetComponent<TMPro.TMP_Text>()&&!r.GetComponentInParent<LODGroup>()).ToArray();if(rs.Length<2)return;var groups=rs.GroupBy(r=>r.shadowCastingMode).ToArray();foreach(var g in groups)Bake(g.ToArray(),t,"Combined "+g.Key);Collision(t);Remove(rs);Prune(t);}
 public static string Main(){
  if(EditorApplication.isPlaying)throw new Exception("Edit mode required");Directory.CreateDirectory(A);AssetDatabase.Refresh();report=new List<string>();var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=primitive.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(primitive);
  var root=GameObject.Find("New_Map").transform;var exp=root.Find("11_Five_Hangar_Farm");var farms=root.Find("12_Farmyards_and_boundaries");int before=root.GetComponentsInChildren<Transform>().Length;
  CompactLODs(root.Find("04_Mini_Village"));CompactLODs(farms);CompactLODs(exp.Find("S - Farm supplies and cottage"));
  foreach(var h in exp.Cast<Transform>().Where(t=>t.name.StartsWith("Hangar ")).ToArray()){
   var doors=h.Cast<Transform>().First(t=>t.name.StartsWith("Locked "));foreach(var leaf in doors.Cast<Transform>().Where(t=>t.name.Contains("door -")).ToArray())Flat(leaf);
   var fittings=new GameObject("Door track and lock fittings").transform;fittings.SetParent(doors,false);foreach(var t in doors.Cast<Transform>().Where(t=>t.GetComponent<MeshRenderer>()).ToArray())t.SetParent(fittings,true);Flat(fittings);
  }
  Flat(exp.Find("S - Farm supplies and cottage/Farm supplies shop"));
  // Compact non-LOD village fence pieces in spatial chunks; keep the vehicle independent.
  foreach(var area in new[]{root.Find("04_Mini_Village"),farms}){
   var rs=area.GetComponentsInChildren<MeshRenderer>().Where(r=>!r.GetComponentInParent<LODGroup>()&&!r.GetComponent<TMPro.TMP_Text>()&&(r.name.StartsWith("Fence")||r.name.StartsWith("Village gateway"))).ToArray();
   foreach(var cell in rs.GroupBy(r=>Mathf.FloorToInt(r.bounds.center.x/32)+"_"+Mathf.FloorToInt(r.bounds.center.z/32))){var t=new GameObject("Static fence cell "+cell.Key).transform;t.SetParent(area,false);foreach(var r in cell)r.transform.SetParent(t,true);Flat(t);}
  }
  // Archive inactive legacy hangar construction outside the live scene.
  var hall=root.Find("01_Modular_Hangar");var inactive=hall.Cast<Transform>().Where(t=>!t.gameObject.activeSelf).ToArray();if(inactive.Length>0){var archive=new GameObject("Legacy hangar construction - archive");foreach(var t in inactive)t.SetParent(archive.transform,true);PrefabUtility.SaveAsPrefabAsset(archive,A+"/Legacy hangar construction.prefab");Object.DestroyImmediate(archive);}
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);string message="Static mesh renderers consolidated: "+sourceCount+" -> "+resultCount+" (LOD levels retained). Active hierarchy: "+before+" -> "+root.GetComponentsInChildren<Transform>().Length+" transforms. Inactive original hangar construction archived as prefab. Trees, vehicles, grain, shop text and separate door leaves retain independent behavior.";File.WriteAllText("output/NewMap/FiveHangars/static-consolidation.txt",message);return message;
 }
}
